
const titles=['Две команды, одна комната','Договариваемся о словах','Проверяем интервалы','Что остаётся тем же?','Собираем модель','Кто отвечает за правила?','Строим архитектуру','Жизнь брони','Одновременные запросы','Бронь и уведомление','Новое требование','Наша доска решений','В рабочих системах','Зависимости кода'];let scene=0,notes=false,modelStep=0,layerStep=-1,raceStep=0,safe=false,moved=false;
const notesText=[["Скажи", "«В 10:30 в одну комнату пришли две команды. Обе считают, что забронировали её».", "Спроси", "Что должно проверять приложение? Если ответов нет, спроси: «Можно ли начать новую встречу ровно в момент окончания предыдущей?»", "Договоритесь", "В одной комнате встречи не пересекаются. Соседние встречи разрешены. Отменять бронь может организатор."], ["Скажи", "«Давайте договоримся о словах, чтобы не путаться».", "Объясни", "Комната — место. Бронь — кто и когда занимает это место. Интервал — время начала и конца. Организатор — человек, который создал бронь.", "Спроси", "Если встречу отменили, должна ли комната освободиться? Отдельный класс встречи нам сейчас не нужен."], ["Покажи", "Передвинь второй интервал. Затем нажми «Проверить правило».", "Объясни", "10:00–11:00 и 10:30–11:30 пересекаются. 10:00–11:00 и 11:00–12:00 не пересекаются. Для начала новой встречи комната уже свободна.", "Добавь", "Начало должно быть раньше конца. Это правило самого интервала."], ["Нажми", "«Перенести встречу».", "Объясни", "У брони изменилось время, но номер остался 42. Это та же бронь. Такой объект называют сущностью: Entity.", "Сравни", "Два интервала с одинаковыми границами равны. Это объект значения: Value Object. Он может быть классом, не обязательно struct."], ["Сначала спроси", "Какие классы предлагаете? Затем раскрывай наш вариант кнопкой.", "Объясни", "Room хранит сведения о комнате. Booking хранит одну бронь. TimeInterval хранит начало и конец. RoomSchedule видит брони одной комнаты и ищет пересечения.", "Не требуй точного совпадения", "Другой вариант тоже допустим. Попроси объяснить, где находится проверка пересечений. Здесь рассматриваем расписание выбранного периода, а не всю историю комнаты."], ["Скажи", "«Сначала у нас был сайт. Потом добавился бот».", "Спроси", "Нужно ли боту заново писать проверку свободного времени? Что будет, если сайт и бот проверяют по-разному?", "Объясни", "Оба вызывают одни классы бронирования. Booking проверяет своё состояние. RoomSchedule проверяет занятость комнаты. Экран проверяет, что человек ввёл дату в понятном формате."], ["Нажимай", "«Следующий этап запроса». Проговаривай каждый этап.", "Скажи", "«Экран получает ввод. Действие приложения загружает расписание. Классы бронирования проверяют правила. Сохранение записывает результат».", "Объясни папки", "UI — экран. Application — действия пользователя. Domain — правила бронирования. Infrastructure — работа с базой и отправка сообщений. Для учебного приложения достаточно папок в одном проекте.", "Уточни", "Стрелки показывают порядок выполнения. Это не схема зависимостей сборок. Классы правил не должны вызывать экран, Telegram или конкретную базу."], ["Спроси", "Кто может отменить бронь? Что делать при повторной отмене?", "Объясни", "В нашем примере отменяет организатор. Повторная отмена ничего не меняет. Отменённая бронь остаётся в истории, но уже не занимает комнату.", "Свяжи с кодом", "Снаружи вызывают Cancel. Бронь внутри проверяет правило. Если разрешить прямую запись статуса, проверку можно обойти. Код на доске не пишем."], ["Сначала покажи обычный вариант", "Нажми «Показать гонку», затем «Следующий шаг» три раза. Оба запроса прочитали, что время свободно. Оба записали бронь.", "Затем покажи защиту", "Нажми «Добавить проверку версии». Пройди четыре шага. Первый запрос меняет расписание с версии 7 на 8. Второй пытается записать по старой версии 7 и получает отказ.", "Объясни", "Второй запрос перечитывает расписание. Теперь он видит, что время занято. Проверка номера версии и запись должны выполняться одной неделимой операцией. Номер нужен у общего расписания комнаты, а не у каждой новой брони.", "Не усложняй", "Это один способ защиты. В реальном проекте способ зависит от базы данных. Обычная транзакция сама по себе ещё не запрещает пересечения."], ["Спроси", "Сообщение не отправилось. Считать ли бронь отменённой?", "Договоритесь", "В нашем приложении бронь остаётся. Комната занята. Сообщение можно отправить позже.", "Покажи", "Кнопка раскрывает вариант: вместе с бронью записываем задачу на отправку. Отдельный отправитель повторяет попытку при ошибке. Такой подход называют outbox. Дополнительная тема; студентам не нужно реализовывать его сейчас."], ["Скажи", "«Встречу перенесли на два часа позже. Что приложение должно проверить?»", "Покажи", "Нажми «Перенести на 12:00», затем раскрой подсказки. Номер брони остаётся прежним.", "Объясни", "Бронь активна. Действует организатор. Новый интервал корректен. Другие брони не мешают. При проверке не сравниваем бронь с ней самой. При записи снова защищаемся от одновременного изменения расписания."], ["Спроси", "Какие классы у нас получились? За что отвечает каждый? Что останется, если заменить сайт ботом?", "Свяжи с домашками", "ValueType: равенство по содержимому. TaxiOrder: сам заказ проверяет, можно ли начать или закончить поездку. Репозиторий водителей только выдаёт водителя.", "Закончите", "Выберите одно правило и объясните весь путь: кто его проверяет, как сохраняет результат и что увидит человек."]];
const room=()=>`<div class="floor"><div class="table"><i class="chair"></i><i class="chair"></i><i class="chair"></i><i class="chair"></i>Комната «Север»</div><div class="door"></div></div>`;
const prompt=q=>`<div class="question">${q}</div>`;const reveal=(label,body)=>`<div class="controls"><button onclick="this.nextElementSibling.classList.toggle('hidden')">${label}</button><div class="answer hidden">${body}</div></div>`;
const head=(title,lead)=>`<h1>${title}</h1><p class="lead">${lead}</p>`;
function calendar(a=25,b=37.5){return `<div class="calendar"><div class="hours"><span>09:00</span><span>10:00</span><span>11:00</span><span>12:00</span><span>13:00</span></div><div class="trackrow"><strong>«Север»</strong><div class="track"><div class="block" style="left:${a}%;width:25%">Команда А<small>10:00–11:00</small></div><div class="block pink collision" style="left:${b}%;width:25%;top:30px">Команда Б<small>10:30–11:30</small></div></div></div><div class="trackrow"><strong>«Юг»</strong><div class="track"><div class="block green" style="left:60%;width:30%">Свободно до 11:30</div></div></div></div>`}
function model(){return `<svg class="model" viewBox="0 0 1060 410" role="img" aria-label="Модель: расписание комнаты управляет бронями; бронь содержит идентификатор комнаты, организатора и временной интервал"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#617596"/></marker></defs><g class="node ${modelStep<1?'mutedNode':''}"><rect class="box root" x="350" y="20" width="360" height="125" rx="18"/><text class="title" x="375" y="55">Расписание комнаты</text><text class="small" x="375" y="85">RoomSchedule · версия</text><text class="small" x="375" y="113">Не допускает пересечения</text></g><g class="node ${modelStep<2?'mutedNode':''}"><path class="link" d="M440 145 V195 H210 V230" marker-end="url(#arrow)"/><text class="small" x="200" y="187">управляет бронями</text><rect class="box" x="40" y="230" width="340" height="140" rx="18"/><text class="title" x="65" y="265">Бронь · Booking</text><text class="small" x="65" y="297">ID · комната · организатор</text><text class="small" x="65" y="331">Отменить · проверить состояние</text></g><g class="node ${modelStep<3?'mutedNode':''}"><path class="link" d="M620 145 V195 H835 V230" marker-end="url(#arrow)"/><text class="small" x="720" y="187">для одной комнаты</text><rect class="box" x="670" y="230" width="340" height="140" rx="18"/><text class="title" x="695" y="265">Комната · Room</text><text class="small" x="695" y="297">ID, название, вместимость</text><text class="small" x="695" y="331">Место, которое бронируют</text></g><g class="node ${modelStep<4?'mutedNode':''}"><path class="link" d="M380 300 H425" marker-end="url(#arrow)"/><rect class="box vo" x="430" y="250" width="205" height="140" rx="18"/><text class="title" x="450" y="286">Интервал</text><text class="small" x="450" y="317">Начало → конец</text><text class="small" x="450" y="348">Пересекается?</text></g></svg>`}
function race(){const a=['Прочитал: свободно · v7','Проверка пройдена','Сохранил бронь · v8'];const b=safe?['Прочитал: свободно · v7','Проверка пройдена','Запись с v7 отклонена','Перечитал v8: время занято']:['Прочитал: свободно · v7','Проверка пройдена','Сохранил вторую бронь'];return `<div class="race"><div class="request"><div class="person"><span class="avatar">А</span><h2>Запрос А</h2></div>${a.map((x,i)=>`<div class="event ${raceStep<i+1?'pending':''}">${x}</div>`).join('')}</div><div class="store"><div class="cylinder">Расписание<br>комнаты<br><span class="count">${raceStep<3?'0':safe?'1':'2'}</span><br>${raceStep>=3?(safe?'активная бронь':'активные брони'):'активных броней'}</div><span class="badge">${raceStep<3?'Версия 7':safe?'Версия 8':'Конфликт!'}</span></div><div class="request"><div class="person"><span class="avatar pink">Б</span><h2>Запрос Б</h2></div>${b.map((x,i)=>`<div class="event ${raceStep<i+1?'pending':''} ${i>1?(safe?'good':'bad'):''}">${x}</div>`).join('')}</div></div>`}
function render(){let html='';switch(scene){case 0:html=head('В 10:30 пришли обе команды','Обе уверены, что комната забронирована. Начинаем с проблемы.')+`<div class="row"><div class="col">${room()}</div><div class="col sheet"><div class="person"><span class="avatar">А</span><div><h2>«Мы с десяти!»</h2><span class="sub">10:00–11:00</span></div></div><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><div class="person"><span class="avatar pink">Б</span><div><h2>«А мы с половины!»</h2><span class="sub">10:30–11:30</span></div></div></div></div>`+prompt('Что приложение должно разрешать? Что оно должно запрещать?');break;
case 1:html=head('Что мы будем хранить?','Договоримся, что означают комната, бронь и время бронирования.')+`<div class="wordcards">${[['▣','Комната','Место: «Север», 6 человек'],['◷','Бронь','Кто занимает место и когда'],['↔','Интервал','Начало и конец'],['◎','Организатор','Кто может отменить']].map(([icon,t,d])=>`<div class="wordcard"><div class="icon">${icon}</div><b>${t}</b><button style="margin-top:20px" onclick="this.outerHTML='<p>${d}</p>'">Какой смысл?</button></div>`).join('')}</div>`+prompt('Человек отменил встречу. Что должно произойти с бронью комнаты?');break;
case 2:html=head('Две брони: разрешим или запретим?','Двигай второй интервал. Границы встреч тоже имеют значение.')+`<div class="sheet"><div class="hours" style="margin-left:0"><span>09:00</span><span>10:00</span><span>11:00</span><span>12:00</span><span>13:00</span></div><div class="timeline"><div class="block" style="left:25%;width:25%">А: 10:00–11:00</div></div><div class="timeline"><div id="moving" class="block pink" style="left:37.5%;width:25%">Б: 10:30–11:30</div></div><div class="controls"><label for="time">Начало второй брони</label><input class="range" id="time" type="range" min="0" max="180" step="15" value="90" oninput="interval(this.value)"><span id="timeLabel" class="badge">10:30</span><button onclick="interval(document.getElementById('time').value,true)">Проверить правило</button></div><div id="intervalAnswer" class="answer hidden" aria-live="polite"></div></div>`+prompt('Встречи 10:00–11:00 и 11:00–12:00 пересекаются?');break;
case 3:html=head('Меняется время. Меняется ли бронь?','Бронь можно перенести. Её номер при этом остаётся прежним.')+`<div class="grid two"><div class="sheet"><span class="badge">Сущность (Entity)</span><h2 style="margin-top:20px">Бронь №42</h2><div class="huge" id="bookingTime">10:00–11:00</div><p>Комната «Север»</p><button onclick="document.getElementById('bookingTime').textContent='12:00–13:00';this.disabled=true">Перенести встречу</button><p class="sub">ID остаётся 42. Это та же бронь.</p></div><div class="sheet"><span class="badge" style="background:#d7efeb;color:#216b62">Объект значения (Value Object)</span><h2 style="margin-top:20px">Два интервала</h2><div class="huge">10:00–11:00</div><div class="accent" style="padding:15px">=</div><div class="huge">10:00–11:00</div><p class="sub">Начало и конец совпадают — интервалы равны. Номер интервалу не нужен.</p></div></div>`+prompt('Если две разные команды забронировали одно время, их брони равны?');break;
case 4:html=head('Какие классы нам нужны?','Сначала предложите классы. Кнопка покажет наш вариант по одному объекту.')+`<div class="sheet">${model()}<div class="controls"><button class="primary" onclick="modelStep=Math.min(4,modelStep+1);render()">Показать следующий объект</button><button onclick="modelStep=0;render()">Скрыть модель</button><span class="sub">${modelStep} / 4</span></div></div>`+prompt('Какой класс видит все брони комнаты и может найти пересечение?');break;
case 5:html=head('Где проверять правила?','Бронировать можно на сайте и через бота. Правила должны быть одинаковыми.')+`<div class="grid two"><div class="sheet"><h2 class="bad">Правила разбросаны</h2><div class="badmap"><div class="mapbox rule">Веб-экран: проверяет интервалы</div><div class="mapbox rule">Бот: проверяет интервалы ещё раз</div><div class="mapbox rule">Админка: просто меняет поля</div></div><span class="sub">Три входа — три версии одного правила.</span></div><div class="sheet"><h2 class="good">Правила в классах бронирования</h2><div class="goodmap"><div class="mapbox">Веб / бот / админка</div><div class="linkline">↓ просят приложение создать бронь</div><div class="mapbox core">Расписание: проверяет занятость</div><div class="mapbox core">Бронь: проверяет своё состояние</div></div><span class="sub">Сайт и бот вызывают одни и те же проверки.</span></div></div>`+prompt('Кто проверяет, что дата введена правильно? Кто проверяет, что комната свободна?');break;
case 6:html=head('Кто что делает в приложении?','Нажали «Забронировать». Проследим, что происходит дальше.')+`<div class="row"><div class="col">${[['Экран или бот','Получает комнату и время от человека'],['Действие приложения','Находит расписание и просит создать бронь'],['Классы бронирования','Проверяют правила комнаты и брони'],['Сохранение','Записывает бронь. Не допускает двойную запись']].map(([t,d],i)=>`<div class="layer ${layerStep===i?'active':''}"><span class="num">${i+1}</span><b>${t}</b><span>${d}</span></div>${i<3?'<div class="arrow">↓</div>':''}`).join('')}<div class="controls"><button class="primary" onclick="layerStep=(layerStep+1)%4;render()">Следующий этап запроса</button><button onclick="layerStep=-1;render()">Сбросить</button></div></div><div class="col sheet dark"><h2>Правила работают и без сайта</h2><p class="sub">Классы бронирования не рисуют экран и не отправляют сообщения.</p><h3>В одном приложении</h3><div class="pill">UI</div><div class="pill">Application</div><div class="pill">Domain</div><div class="pill">Infrastructure</div><p class="sub">Папки помогают ориентироваться. Отдельные сборки могут ограничивать зависимости.</p><h3>Кто кого использует</h3><p class="sub">Экран вызывает действие приложения. Оно вызывает классы бронирования. Эти классы не вызывают экран.</p></div></div>`+prompt('Мы добавили бота. Нужно ли заново писать проверку занятости комнаты?');break;
case 7:html=head('Статус меняется через действие','Бронь сама проверяет, можно ли её отменить.')+`<div class="sheet"><div class="statebar"><div class="state">Активна</div><div class="statearrow">→<br><span class="sub">Отменить</span></div><div class="state cancel">Отменена</div></div><div class="grid two"><div class="mapbox core">Организатор отменяет свою бронь</div><div class="mapbox rule">Другой человек пытается отменить</div></div><div class="controls"><button onclick="document.getElementById('stateAnswer').classList.toggle('hidden')">Раскрыть правило</button></div><div id="stateAnswer" class="answer hidden">Отменяет только организатор. Отменённая бронь остаётся в истории и больше не занимает время.</div></div>`+prompt('Что будет, если любой код сможет просто написать: «статус = отменена»?');break;
case 8:html=head(safe?'Повторяем с защитой при сохранении':'Обе проверки прошли. Обе брони записались.',safe?'Версия — номер состояния расписания. При записи проверяем, что никто не изменил его раньше нас.':'Пока один запрос проверял время, другой мог его занять.')+race()+`<div class="controls"><button class="primary" onclick="raceStep=Math.min(${safe?4:3},raceStep+1);render()">Следующий шаг</button><button onclick="raceStep=0;render()">Сначала</button><button class="${safe?'on':''}" onclick="safe=!safe;raceStep=0;render()">${safe?'Показать гонку':'Добавить проверку версии'}</button><span class="badge">Шаг ${raceStep} / ${safe?4:3}</span></div>`+prompt(safe?'Почему второй запрос снова проверяет доступность?':'Почему проверки «время свободно» оказалось недостаточно?');break;
case 9:html=head('Бронь есть. Telegram лежит.','Бронь записали. Сообщение организатору отправить не удалось.')+`<div class="sheet"><div class="notification"><div class="notifybox"><big class="good">✓</big><h2>Бронь сохранена</h2><span class="badge">Комната занята</span></div><div class="statearrow">→</div><div class="notifybox"><big class="bad">×</big><h2>Сообщение не ушло</h2><span class="badge">Ошибка доставки</span></div></div><div id="outbox" class="hidden"><div class="mapbox core">Записываем вместе: бронь и задачу «отправить сообщение»</div><div class="linkline">↓</div><div class="mapbox">Отправитель читает задачу. При ошибке пробует ещё раз.</div></div><button onclick="document.getElementById('outbox').classList.toggle('hidden')">Показать вариант с повторной доставкой</button></div>`+prompt('Неотправленное сообщение должно отменить бронь?');break;
case 10:html=head('Теперь встречу можно переносить','Организатор хочет изменить время уже созданной брони.')+`<div class="grid two"><div class="sheet"><span class="badge">BookingId = 42</span><h2 style="margin-top:20px">${moved?'12:00–13:00':'10:00–11:00'}</h2>${room()}<div class="controls"><button class="primary" onclick="moved=!moved;render()">${moved?'Вернуть исходное время':'Перенести на 12:00'}</button></div></div><div class="sheet"><h2>Что надо проверить?</h2><div class="empty" id="moveRules">Сначала ответы группы</div><button style="margin-top:20px" onclick="document.getElementById('moveRules').innerHTML='Бронь активна<br>Переносит организатор<br>Начало раньше конца<br>Нет пересечений с другими бронями<br>При записи снова проверяем версию расписания'">Показать подсказки</button><p class="sub">При проверке исключаем саму переносимую бронь.</p></div></div>`+prompt('Какие правила уже есть? Какую операцию добавим?');break;
case 11:html=head('Что мы решили?','Назовите классы. Объясните, какие проверки делает каждый из них.')+`<div class="summarygrid">${[['Наш словарь','Комната · бронь · организатор · интервал'],['Кто проверяет правила','Интервал — границы. Бронь — состояние. Расписание — занятость.'],['Наша архитектура','Экран → действие приложения → классы бронирования → сохранение'],['Два запроса одновременно','Классы проверяют свободное время. Сохранение не даёт двум запросам занять его одновременно.']].map(([a,b])=>`<div class="sheet"><h2>${a}</h2><p>${b}</p></div>`).join('')}</div>`+prompt('Что из этого узнаёте в домашних заданиях ValueType и TaxiOrder?')+`<footer>Учебный пример. Здесь обсуждаем устройство приложения и его правила. Код писать не требуется.</footer>`;break;case 12:html=companiesHtml();break;case 13:html=dependenciesHtml();break;}document.getElementById('stage').innerHTML=html;document.getElementById('dots').innerHTML=titles.map((t,i)=>`<button class="dot ${i===scene?'current':''}" title="${t}" aria-label="${i+1}. ${t}" ${i===scene?'aria-current="step"':''} onclick="go(${i})">${i+1}</button>`).join('');document.getElementById('position').textContent=`${scene+1} / ${titles.length} · ${titles[scene]}`;document.getElementById('prev').disabled=scene===0;document.getElementById('next').disabled=scene===titles.length-1;document.getElementById('progress').style.width=((scene+1)/titles.length*100)+'%';document.getElementById('teacher').innerHTML='<h2>Тебе для ведения</h2>'+notesText[scene].map((s,i)=>i%2===0?`<b>${s}</b>`:`<p>${s}</p>`).join('');}
function go(n){scene=Math.max(0,Math.min(titles.length-1,n));render();window.scrollTo(0,0)}function interval(v,show=false){const n=Number(v),h=Math.floor((540+n)/60),m=(540+n)%60;const start=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`,end=`${String(h+1).padStart(2,'0')}:${String(m).padStart(2,'0')}`;document.getElementById('moving').style.left=(n/240*100)+'%';document.getElementById('moving').textContent=`Б: ${start}–${end}`;document.getElementById('timeLabel').textContent=start;const a=document.getElementById('intervalAnswer');a.classList.toggle('hidden',!show);a.textContent=n<120&&n+60>60?'Запрещаем: интервалы одной комнаты пересекаются.':'Разрешаем: интервалы не пересекаются.';}
document.getElementById('prev').onclick=()=>go(scene-1);document.getElementById('next').onclick=()=>go(scene+1);document.getElementById('notesButton').onclick=()=>{notes=!notes;document.getElementById('teacher').classList.toggle('hidden',!notes);document.getElementById('notesButton').setAttribute('aria-pressed',String(notes))};document.getElementById('fullButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{document.getElementById('fullButton').textContent='Используй F11'}};document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(scene+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(scene-1)}});